package org.dromara.sports.platform.registry;
import cn.dev33.satoken.annotation.SaCheckPermission;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.dromara.common.core.domain.R;
import org.dromara.common.satoken.utils.LoginHelper;
import org.dromara.sports.platform.core.BusinessSupport;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import java.util.*;
@RestController @RequestMapping("/sports/platform/management") @SaCheckPermission("sports:platform:manage") @RequiredArgsConstructor
public class CapabilityManagementController {
 private final CapabilityRegistry registry;private final JdbcTemplate db;private final ObjectMapper json;
 @GetMapping public R<JsonNode> catalog(){var n=json.createObjectNode();n.set("definitions",json.valueToTree(registry.definitions().stream().map(d->Map.of("definition",d,"definitionHash",registry.fingerprint(d))).toList()));n.set("modules",json.valueToTree(registry.modules()));n.set("activations",BusinessSupport.safeJson(json,db.queryForList("SELECT a.code,a.channel,a.enabled,v.revision,v.source_hash,v.status,v.definition FROM asp_capability_activation a JOIN asp_capability_version v ON v.id=a.capability_version_id AND v.code=a.code ORDER BY a.code,a.channel")));n.set("agents",BusinessSupport.safeJson(json,db.queryForList("SELECT a.id,a.code,a.name,a.layer,a.status,v.model_name,v.revision,v.budget::text,v.playbook_hash,v.tool_catalog::text,v.skill_catalog::text,v.business_map::text FROM asp_agent a JOIN asp_agent_version v ON v.agent_id=a.id AND v.status='active' AND v.revision=(SELECT MAX(latest.revision) FROM asp_agent_version latest WHERE latest.agent_id=a.id AND latest.status='active') ORDER BY a.code")));return R.ok(n);}
 @PostMapping("/release") @Transactional public R<Void> release(@RequestBody Release in){if(!LoginHelper.isSuperAdmin())throw BusinessSupport.fail("开放能力须由平台负责人办理",403);var d=registry.definition(in.code());if(!Set.of("ui","agent","system").contains(in.channel())||in.channel().equals("agent")&&!d.agent())throw BusinessSupport.fail("该渠道不允许开放",400);if(!registry.fingerprint(d).equals(in.definitionHash())||in.evidenceHash()==null||!in.evidenceHash().matches("[a-f0-9]{64}"))throw BusinessSupport.fail("请绑定当前定义与本机验收记录的校验值",409);db.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"capability:"+in.code());var versions=db.queryForList("SELECT id FROM asp_capability_version WHERE code=? AND source_hash=? AND status='published' ORDER BY revision DESC LIMIT 1",in.code(),in.definitionHash());long id;if(versions.isEmpty()){id=BusinessSupport.nextId();int revision=db.queryForObject("SELECT COALESCE(MAX(revision),0)+1 FROM asp_capability_version WHERE code=?",Integer.class,in.code());var definition=json.valueToTree(d);((com.fasterxml.jackson.databind.node.ObjectNode)definition).put("evidenceHash",in.evidenceHash());db.update("INSERT INTO asp_capability_version(id,code,revision,definition,source_hash,status,create_by) VALUES(?,?,?,?::jsonb,?,'published',?)",id,in.code(),revision,definition.toString(),in.definitionHash(),LoginHelper.getUserId());}else id=BusinessSupport.number(versions.get(0).get("id"));db.update("INSERT INTO asp_capability_activation(id,code,capability_version_id,channel,enabled,create_by) VALUES(?,?,?,?,?,?) ON CONFLICT(code,channel) DO UPDATE SET capability_version_id=excluded.capability_version_id,enabled=excluded.enabled,version=asp_capability_activation.version+1,update_time=CURRENT_TIMESTAMP,update_by=excluded.create_by",BusinessSupport.nextId(),in.code(),id,in.channel(),in.enabled(),LoginHelper.getUserId());var record=json.createObjectNode().put("code",in.code()).put("channel",in.channel()).put("enabled",in.enabled()).put("definitionHash",in.definitionHash()).put("evidenceHash",in.evidenceHash());db.update("INSERT INTO asp_action_execution(id,action_code,actor_type,actor_id,channel,request_key,payload_hash,status,result_reference,occurred_at) VALUES(?,'capability.release','admin',?,'ui',?,?,'succeeded',?::jsonb,CURRENT_TIMESTAMP)",BusinessSupport.nextId(),LoginHelper.getUserId(),java.util.UUID.randomUUID().toString(),org.dromara.sports.platform.core.JsonFingerprint.hash(record),record.toString());return R.ok();}
 public record Release(String code,String channel,boolean enabled,String definitionHash,String evidenceHash){}
}
